INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the general formula relationship used to convert yarn count between the Tex system and the Ne (English cotton) system?', '["Tex = 590.5 / Ne (approximately), since the two systems are inversely related through a fixed conversion constant","Tex and Ne are always numerically identical regardless of yarn count","Tex = Ne × 840 with no other conversion factor needed","There is no mathematical relationship between Tex and Ne; they measure completely unrelated properties"]'::jsonb, 'Tex = 590.5 / Ne (approximately), since the two systems are inversely related through a fixed conversion constant', 'Since Tex is a direct system (grams/1000m) and Ne is an indirect system (hanks of 840yd per lb), they are inversely related; the standard conversion constant gives Tex ≈ 590.5 / Ne (and equivalently Ne ≈ 590.5 / Tex) for cotton-system yarns.', 2, '{"tex-ne-conversion"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does ''twist multiplier'' (or twist factor) express, as opposed to simply stating ''twist per inch'' (TPI) alone?', '["A standardized value relating twist level to yarn count, allowing fair twist-level comparison between yarns of different counts (since appropriate TPI naturally differs with count)","The exact color of the yarn after dyeing","The total number of plies in a folded/plied yarn only","A measure of fiber moisture content, unrelated to twist"]'::jsonb, 'A standardized value relating twist level to yarn count, allowing fair twist-level comparison between yarns of different counts (since appropriate TPI naturally differs with count)', 'Since finer yarns naturally need higher TPI than coarser yarns to achieve a similar ''twist liveliness''/structural effect, twist multiplier (typically TM = TPI / √Ne for cotton count) normalizes this relationship, allowing meaningful twist-level comparison across different yarn counts on a common scale.', 2, '{"twist-multiplier-formula"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does the term ''spinning triangle'' refer to at the front (delivery) end of a ring frame''s drafting zone?', '["The small triangular zone where the flat, drafted fiber strand converges and begins to receive twist just before becoming rounded yarn","A triangular warning label affixed to spinning machinery for safety purposes","The triangular cross-section shape of the finished yarn itself","A triangular arrangement of three spindles on the ring frame"]'::jsonb, 'The small triangular zone where the flat, drafted fiber strand converges and begins to receive twist just before becoming rounded yarn', 'The spinning triangle is the small, triangular-shaped zone right after the front drafting rollers where the flat, untwisted fiber ribbon converges and twist begins to be inserted, transforming it into round yarn — a zone where edge fibers can be lost or improperly incorporated if not well controlled (part of what compact spinning specifically improves).', 2, '{"spinning-triangle"}'::text[]);
COMMIT;
